package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type symbol struct {
	name string
	path string
	pos  token.Position
}

type count struct {
	sym    symbol
	calls  int
	sites  map[string]int
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax |
			packages.NeedTypes | packages.NeedTypesInfo | packages.NeedCompiledGoFiles,
		Dir:  "/bench/repo",
		Tests: true,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load: %v\n", err)
		os.Exit(1)
	}

	// Collect functions declared under internal/
	declared := map[types.Object]*count{}
	fset := token.NewFileSet()

	for _, pkg := range pkgs {
		if pkg.Fset != nil {
			fset = pkg.Fset
		}
		if len(pkg.Errors) > 0 {
			for _, e := range pkg.Errors {
				fmt.Fprintf(os.Stderr, "pkg err %s: %v\n", pkg.PkgPath, e)
			}
		}
		if pkg.TypesInfo == nil {
			continue
		}
		for _, file := range pkg.Syntax {
			pos := fset.Position(file.Pos())
			if !strings.Contains(pos.Filename, "/internal/") {
				continue
			}
			if strings.HasSuffix(pos.Filename, "_test.go") {
				continue
			}
			ast.Inspect(file, func(n ast.Node) bool {
				fn, ok := n.(*ast.FuncDecl)
				if !ok || fn.Name == nil {
					return true
				}
				obj := pkg.TypesInfo.Defs[fn.Name]
				if obj == nil {
					return true
				}
				recv := ""
				if fn.Recv != nil && len(fn.Recv.List) > 0 {
					recv = exprString(fn.Recv.List[0].Type)
				}
				name := fn.Name.Name
				if recv != "" {
					name = recv + "." + name
				}
				rel, _ := filepath.Rel("/bench/repo", pos.Filename)
				declared[obj] = &count{
					sym: symbol{
						name: name,
						path: rel,
						pos:  fset.Position(fn.Pos()),
					},
					sites: map[string]int{},
				}
				return true
			})
		}
	}

	fmt.Fprintf(os.Stderr, "declared internal funcs: %d\n", len(declared))

	// Count call sites
	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil {
			continue
		}
		fset = pkg.Fset
		for ident, obj := range pkg.TypesInfo.Uses {
			c, ok := declared[obj]
			if !ok {
				continue
			}
			pos := fset.Position(ident.Pos())
			// skip the declaration itself
			if pos.Filename == c.sym.pos.Filename && pos.Line == c.sym.pos.Line {
				continue
			}
			c.calls++
			site := fmt.Sprintf("%s:%d", pos.Filename, pos.Line)
			c.sites[site]++
		}
	}

	var list []*count
	for _, c := range declared {
		list = append(list, c)
	}
	sort.Slice(list, func(i, j int) bool {
		if list[i].calls != list[j].calls {
			return list[i].calls > list[j].calls
		}
		return list[i].sym.name < list[j].sym.name
	})

	n := 40
	if len(list) < n {
		n = len(list)
	}
	for i := 0; i < n; i++ {
		c := list[i]
		fmt.Printf("%4d  unique-sites=%-4d  %s  %s:%d\n", c.calls, len(c.sites), c.sym.name, c.sym.path, c.sym.pos.Line)
	}
}

func exprString(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.IndexExpr:
		return exprString(t.X)
	default:
		return fmt.Sprintf("%T", e)
	}
}

