#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";

# Collect all .go files
my @gofiles;
find(sub {
    return unless /\.go$/;
    my $p = $File::Find::name;
    return if $p =~ m{/\.git/};
    push @gofiles, $p;
}, $root);

print STDERR "go files: " . scalar(@gofiles) . "\n";

# Parse function declarations under internal/ (non-test)
# key: "pkgpath::recv::name"
my %funcs; # key => {name, recv, pkg, file, line, exported}

sub rel {
    my $p = shift;
    $p =~ s{^\Q$root/}{};
    return $p;
}

sub pkgpath_from_file {
    my $f = shift;
    $f =~ s{^\Q$root/}{};
    $f =~ s{/[^/]+\.go$}{};
    return $f;
}

for my $f (@gofiles) {
    next unless $f =~ m{/internal/};
    next if $f =~ /_test\.go$/;
    open my $fh, "<", $f or die $!;
    my $pkg;
    my $line = 0;
    my $in_block_comment = 0;
    while (my $l = <$fh>) {
        $line++;
        if ($in_block_comment) {
            if ($l =~ s{.*?\*/}{}) {
                $in_block_comment = 0;
            } else {
                next;
            }
        }
        $l =~ s{/\*.*?\*/}{}g;
        if ($l =~ s{/\*.*}{}) {
            $in_block_comment = 1;
        }
        $l =~ s{//.*}{};
        if (!$pkg && $l =~ /^\s*package\s+(\w+)/) {
            $pkg = $1;
            next;
        }
        # func (recv) Name(
        if ($l =~ /^\s*func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
            my $recv_raw = $1 // "";
            my $name = $2;
            my $recv = "";
            if ($recv_raw ne "") {
                # last token is type
                $recv_raw =~ s/\s+/ /g;
                $recv_raw =~ s/^\s+|\s+$//g;
                if ($recv_raw =~ /(\*?[\w.]+)$/) {
                    $recv = $1;
                }
            }
            my $key = pkgpath_from_file($f) . "::" . $recv . "::" . $name;
            $funcs{$key} = {
                name => $name,
                recv => $recv,
                pkg  => $pkg,
                pkgpath => pkgpath_from_file($f),
                file => rel($f),
                line => $line,
            };
        }
    }
    close $fh;
}

print STDERR "declared funcs: " . scalar(keys %funcs) . "\n";

# Build file->package map
my %file_pkg;
my %file_pkgpath;
for my $f (@gofiles) {
    open my $fh, "<", $f or die $!;
    while (my $l = <$fh>) {
        if ($l =~ /^\s*package\s+(\w+)/) {
            $file_pkg{$f} = $1;
            $file_pkgpath{$f} = pkgpath_from_file($f);
            last;
        }
    }
    close $fh;
}

# Count name frequencies for uniqueness awareness
my %name_decl_count;
for my $k (keys %funcs) {
    $name_decl_count{$funcs{$k}{name}}++;
}

# For each file, extract identifiers used as calls: Ident(  or .Ident(
# We'll do a reasonably careful scan.

# Pre-index funcs by name and by pkg+name
my %by_name;
my %by_pkg_name;
my %by_pkgpath_name;
for my $k (keys %funcs) {
    my $f = $funcs{$k};
    push @{$by_name{$f->{name}}}, $k;
    push @{$by_pkg_name{$f->{pkg} . "::" . $f->{name}}}, $k;
    push @{$by_pkgpath_name{$f->{pkgpath} . "::" . $f->{name}}}, $k;
}

# Count calls
my %calls; # key => count
my %call_sites; # key => {file:line => 1}

# Import aliases: file => { alias => pkgpath-ish }
# We'll map import last component to package name.

sub parse_imports {
    my ($content) = @_;
    my %imp; # alias_or_name => import_path
    if ($content =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s{//.*}{};
            if ($line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
                my $alias = $1;
                my $path = $2;
                my $name = $path;
                $name =~ s{.*/}{};
                $imp{$alias || $name} = $path;
            }
        }
    }
    while ($content =~ /import\s+(?:(\w+)\s+)?"([^"]+)"/g) {
        my $alias = $1;
        my $path = $2;
        my $name = $path;
        $name =~ s{.*/}{};
        $imp{$alias || $name} = $path;
    }
    return \%imp;
}

# Only count Go files (including tests) as callers
for my $f (@gofiles) {
    open my $fh, "<", $f or die $!;
    my $content = do { local $/; <$fh> };
    close $fh;

    my $imps = parse_imports($content);
    my $this_pkg = $file_pkg{$f} // "";
    my $this_pkgpath = $file_pkgpath{$f} // "";

    # Strip comments roughly
    $content =~ s{/\*.*?\*/}{}sg;
    # Keep line numbers: replace comment lines with spaces of same length? 
    # Simpler: process line by line after stripping //
    my @lines = split /\n/, $content;
    # re-read for accurate line numbers after block comment strip is imperfect
    # Re-read raw and strip per line
}

# Re-do with line-accurate scan
for my $f (@gofiles) {
    open my $fh, "<", $f or die $!;
    my @raw = <$fh>;
    close $fh;
    my $full = join("", @raw);
    my $imps = parse_imports($full);
    my $this_pkg = $file_pkg{$f} // "";
    my $this_pkgpath = $file_pkgpath{$f} // "";

    my $in_block = 0;
    my $lineno = 0;
    for my $l (@raw) {
        $lineno++;
        if ($in_block) {
            if ($l =~ s{.*?\*/}{}) {
                $in_block = 0;
            } else {
                next;
            }
        }
        $l =~ s{/\*.*?\*/}{}g;
        if ($l =~ s{/\*.*}{}) {
            $in_block = 1;
        }
        $l =~ s{//.*}{};

        # Find calls:  [optional qualifier.]Ident(
        # Avoid func declarations
        next if $l =~ /^\s*func\s/;

        while ($l =~ /(?<![.\w])(?:(\w+)\.)?(\w+)\s*\(/g) {
            my $qual = $1;
            my $name = $2;
            next if $name =~ /^(if|for|switch|select|return|go|defer|range|func|make|new|append|len|cap|copy|delete|close|panic|recover|complex|real|imag)$/;

            my @candidates;
            if (defined $qual && $qual ne "") {
                # qualified call: pkg.Func or recv.Method
                if (exists $imps->{$qual}) {
                    my $ipath = $imps->{$qual};
                    # match internal packages
                    if ($ipath =~ m{internal/}) {
                        my $suffix = $ipath;
                        $suffix =~ s{.*github.com/usememos/memos/}{};
                        if (exists $by_pkgpath_name{"$suffix::$name"}) {
                            @candidates = @{$by_pkgpath_name{"$suffix::$name"}};
                            # prefer functions (no recv) for pkg.Func
                            my @funcs_only = grep { $funcs{$_}{recv} eq "" } @candidates;
                            @candidates = @funcs_only if @funcs_only;
                        }
                    }
                } else {
                    # likely a method call: x.Method(
                    if (exists $by_name{$name}) {
                        my @meths = grep { $funcs{$_}{recv} ne "" } @{$by_name{$name}};
                        # if unique method name among internal decls
                        if (@meths == 1) {
                            @candidates = @meths;
                        } elsif (@meths > 1) {
                            # if all same name but we can't resolve, skip unless unique recv types still same name
                            # only assign if name is unique among ALL internal decls that are methods
                            # skip ambiguous
                        }
                    }
                }
            } else {
                # unqualified: same-package function (or locally defined)
                if (exists $by_pkgpath_name{"$this_pkgpath::$name"}) {
                    my @cands = @{$by_pkgpath_name{"$this_pkgpath::$name"}};
                    my @funcs_only = grep { $funcs{$_}{recv} eq "" } @cands;
                    @candidates = @funcs_only if @funcs_only;
                    # also same-package methods called without selector? uncommon in Go
                }
            }

            for my $k (@candidates) {
                # Don't count the declaration line
                if (rel($f) eq $funcs{$k}{file} && $lineno == $funcs{$k}{line}) {
                    next;
