#!/usr/bin/perl
use strict;
use warnings;

my $root = "/bench/repo";
my @gofiles = grep { $_ ne "" && !m{/\.git/} } split /\n/, `find $root -name '*.go' -type f`;

sub rel {
    my $p = shift;
    $p =~ s{^\Q$root/}{};
    return $p;
}
sub pkgpath_from_file {
    my $f = shift;
    $f = rel($f);
    $f =~ s{/[^/]+\.go$}{};
    return $f;
}

