my %funcs; # key => hash
for my $f (@gofiles) {
    next unless $f =~ m{/internal/};
    next if $f =~ /_test\.go$/;
    open my $fh, "<", $f or die $!;
    my $pkg;
    my $line = 0;
    my $in_block = 0;
    while (my $l = <$fh>) {
        $line++;
        if ($in_block) { if ($l =~ s{.*?\*/}{}) { $in_block=0 } else { next } }
        $l =~ s{/\*.*?\*/}{}g;
        if ($l =~ s{/\*.*}{}) { $in_block=1 }
        $l =~ s{//.*}{};
        if (!$pkg && $l =~ /^\s*package\s+(\w+)/) { $pkg = $1; next }
        if ($l =~ /^\s*func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
            my $recv_raw = $1 // "";
            my $name = $2;
            my $recv = "";
            if ($recv_raw ne "") {
                $recv_raw =~ s/\s+/ /g;
                $recv_raw =~ s/^\s+|\s+$//g;
                $recv = $1 if $recv_raw =~ /(\*?[\w.]+)$/;
            }
            my $key = pkgpath_from_file($f) . "::" . $recv . "::" . $name;
            $funcs{$key} = {
                name => $name, recv => $recv, pkg => $pkg,
                pkgpath => pkgpath_from_file($f),
                file => rel($f), line => $line,
                is_func => ($recv eq ""),
            };
        }
    }
    close $fh;
}

print "DECLARED: " . scalar(keys %funcs) . "\n";
my $nfunc = grep { $funcs{$_}{is_func} } keys %funcs;
my $nmeth = (scalar keys %funcs) - $nfunc;
print "  funcs=$nfunc methods=$nmeth\n";

