for my $k (keys %funcs) {
    my $f = $funcs{$k};
    $name_count{$f->{name}}++;
    if ($f->{is_func}) {
        push @{$by_pkgpath_name{$f->{pkgpath} . "::" . $f->{name}}}, $k;
    } else {
        push @{$by_name_methods{$f->{name}}}, $k;
    }
}

my %calls;
my %sites;

for my $f (@gofiles) {
    my $content = $file_content{$f};
    # strip comments keeping newlines
    $content =~ s{/\*.*?\*/}{ my $x=$&; $x =~ s/[^\n]/ /g; $x }sge;
    my $imps = $file_imports{$f};
    my $this_pkgpath = $file_pkgpath{$f};

    my $lineno = 0;
    for my $l (split /\n/, $content) {
        $lineno++;
        $l =~ s{//.*}{};
        next if $l =~ /^\s*func\s/;

        while ($l =~ /(?<![.\w])(?:(\w+)\.)?(\w+)\s*\(/g) {
            my ($qual, $name) = ($1, $2);
            next if $name =~ /^(if|for|switch|select|return|go|defer|range|func|make|new|append|len|cap|copy|delete|close|panic|recover|complex|real|imag|nil|true|false)$/;

            my @cands;
            if (defined $qual && $qual ne "") {
                if (exists $imps->{$qual}) {
                    my $ipath = $imps->{$qual};
                    if ($ipath =~ m{(internal/.+)$}) {
                        my $suffix = $1;
                        if (exists $by_pkgpath_name{"${suffix}::${name}"}) {
                            @cands = @{$by_pkgpath_name{"${suffix}::${name}"}};
                        }
                    }
                } else {
                    # method call: only if unique internal method name AND
                    # this file is in declaring package or imports that package
                    my $meths = $by_name_methods{$name};
                    if ($meths && @$meths == 1) {
                        my $k = $meths->[0];
                        my $decl_pp = $funcs{$k}{pkgpath};
                        my $imports_it = 0;
                        for my $p (values %$imps) {
                            $imports_it = 1 if $p =~ m{\Q$decl_pp\E$};
                        }
                        if ($this_pkgpath eq $decl_pp || $imports_it) {
                            @cands = ($k);
                        }
                    }
                }
            } else {
                # unqualified same-package function
                if (exists $by_pkgpath_name{"$this_pkgpath::$name"}) {
                    @cands = @{$by_pkgpath_name{"$this_pkgpath::$name"}};
                }
            }

            for my $k (@cands) {
                next if rel($f) eq $funcs{$k}{file} && $lineno == $funcs{$k}{line};
                $calls{$k}++;
                $sites{$k}{rel($f).":$lineno"}++;
            }
        }
    }
}

print "\n=== TOP 40 ===\n";
my @sorted = sort { ($calls{$b}||0) <=> ($calls{$a}||0) || $funcs{$a}{name} cmp $funcs{$b}{name} } keys %funcs;
for my $i (0..39) {
    last if $i > $#sorted;
    my $k = $sorted[$i];
    my $c = $calls{$k} || 0;
    last if $c == 0;
    my $f = $funcs{$k};
    my $sym = $f->{recv} ? "$f->{recv}.$f->{name}" : $f->{name};
    printf "%4d  sites=%-4d  %-42s  %s:%d\n", $c, scalar(keys %{$sites{$k}||{}}), $sym, $f->{file}, $f->{line};
}

print "\n=== ALL PACKAGE-LEVEL FUNCS WITH CALLS ===\n";
my @pfuncs = sort { ($calls{$b}||0) <=> ($calls{$a}||0) } grep { $funcs{$_}{is_func} } keys %funcs;
for my $k (@pfuncs) {
    my $c = $calls{$k} || 0;
    last if $c == 0;
    my $f = $funcs{$k};
    printf "%4d  %-40s  %s:%d\n", $c, $f->{name}, $f->{file}, $f->{line};
}

print "\n=== ZERO-CALL PACKAGE-LEVEL (sample of exported) ===\n";
my $z = 0;
for my $k (@pfuncs) {
    next if ($calls{$k}||0) > 0;
    next if $funcs{$k}{name} =~ /^[a-z]/;
    printf "   0  %-40s  %s\n", $funcs{$k}{name}, $funcs{$k}{file};
    last if ++$z >= 20;
}

