#!/usr/bin/perl
use strict;
use warnings;

my $root = "/bench/repo";
my @gofiles = grep { $_ ne "" } split /\n/, `find $root -name '*.go' -type f`;
my @internal_src = grep { m{/internal/} && !/_test\.go$/ } @gofiles;

# collect decls
my %decls; # name => [{recv, file, line, pkgpath}]
for my $f (@internal_src) {
    open my $fh, "<", $f or die $!;
    my $line = 0;
    my $in_block = 0;
    my $pkgpath = $f; $pkgpath =~ s{^\Q$root/}{}; $pkgpath =~ s{/[^/]+$}{};
    while (my $l = <$fh>) {
        $line++;
        if ($in_block) { if ($l =~ s{.*?\*/}{}) { $in_block=0 } else { next } }
        $l =~ s{/\*.*?\*/}{}g;
        if ($l =~ s{/\*.*}{}) { $in_block=1 }
        $l =~ s{//.*}{};
        if ($l =~ /^\s*func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
            my $recv = $1 // "";
            my $name = $2;
            $recv =~ s/.*(\*?[\w.]+)$/$1/;
            push @{$decls{$name}}, { recv => $recv, file => $f, line => $line, pkgpath => $pkgpath, name => $name };
        }
    }
    close $fh;
}

# count token occurrences in all go files (call-like)
my %call_all;
my %call_notest;
my %call_prod_unique; # only count if name has exactly 1 decl

# load all file texts
for my $f (@gofiles) {
    open my $fh, "<", $f or die $!;
    my $content = do { local $/; <$fh> };
    close $fh;
    $content =~ s{/\*.*?\*/}{ my $x=$&; $x =~ s/[^\n]/ /g; $x }sge;
    my $is_test = ($f =~ /_test\.go$/);
    my $rel = $f; $rel =~ s{^\Q$root/}{};
    for my $l (split /\n/, $content) {
        $l =~ s{//.*}{};
        next if $l =~ /^\s*func\s/;
        while ($l =~ /(?<![.\w])(?:\w+\.)?(\w+)\s*\(/g) {
            my $name = $1;
            $call_all{$name}++;
            $call_notest{$name}++ unless $is_test;
        }
    }
}

print "=== UNIQUE-NAME DECLS ranked by all-file call-like count ===\n";
my @names = grep { @{$decls{$_}} == 1 } keys %decls;
@names = sort { ($call_all{$b}||0) <=> ($call_all{$a}||0) } @names;
for my $i (0..25) {
    last if $i > $#names;
    my $n = $names[$i];
    my $d = $decls{$n}[0];
    my $rel = $d->{file}; $rel =~ s{^\Q$root/}{};
    my $sym = $d->{recv} ? "$d->{recv}.$n" : $n;
    printf "%4d all  %4d notest  %-40s  %s:%d\n", $call_all{$n}||0, $call_notest{$n}||0, $sym, $rel, $d->{line};
}

print "\n=== MULTI-DECL NAMES (ambiguous) with high counts ===\n";
my @multi = grep { @{$decls{$_}} > 1 } keys %decls;
@multi = sort { ($call_all{$b}||0) <=> ($call_all{$a}||0) } @multi;
for my $i (0..15) {
    last if $i > $#multi;
    my $n = $multi[$i];
    printf "%4d all  %4d notest  %-20s  decls=%d\n", $call_all{$n}||0, $call_notest{$n}||0, $n, scalar @{$decls{$n}};
    for my $d (@{$decls{$n}}) {
        my $rel = $d->{file}; $rel =~ s{^\Q$root/}{};
        printf "         %s  %s:%d\n", ($d->{recv} ? "$d->{recv}.$n" : $n), $rel, $d->{line};
    }
}

